package com.gomgomapps.math.core;
import java.util.*;import java.math.BigInteger;
/** Whole multipliers, public checks and pictures of the original quantity only. */
public final class WholeFractionProducts {
 private WholeFractionProducts(){}
 public static boolean selected(String id,CurriculumLimits limits){return Set.of("fracMulInt","fracMixedMul").contains(id)&&limits.wholeFractionMultiplier();}
 public static FractionProducts.Givens givens(Question q){if(q==null||!Set.of("fracMulInt","fracMixedMul").contains(q.skillId))return null;var p=FractionProducts.read(q.prompt);if(p==null||!p.operator.equals("*")||(p.left.denominator==1)==(p.right.denominator==1))return null;var fraction=p.left.denominator==1?p.right:p.left;return fraction.mixed()==q.skillId.equals("fracMixedMul")?p:null;}
 public static boolean supports(Question q){return givens(q)!=null;}
 public static Question make(String id,int whole,int numerator,int denominator,int multiplier,boolean reversed){
  if(!Set.of("fracMulInt","fracMixedMul").contains(id)||whole<0||whole>9||id.equals("fracMixedMul")!=(whole>0)||denominator<2||denominator>12||numerator<1||numerator>=denominator||multiplier<1||multiplier>12)throw new IllegalArgumentException("Whole fraction product scope");
  String fraction=(whole==0?"":whole+" ")+numerator+"/"+denominator;String prompt=reversed?multiplier+" × "+fraction:fraction+" × "+multiplier;var value=Rational.of((whole*denominator+numerator)*multiplier,denominator);var q=new Question(id,prompt,"("+whole+"+"+numerator+"/"+denominator+") * "+multiplier,value.toString());q.stepSupport=false;q.answerFormat="fraction";FractionProductRelations.attach(q);q.diagram=new StudyDiagram("wholeFractionProductGiven",new double[]{whole,numerator,denominator,multiplier,reversed?1:0});return q.withInputs(Rational.of(whole*denominator+numerator,denominator),Rational.of(multiplier));
 }
 static Question next(Catalog.Skill skill,Random random,CurriculumLimits limits,Map<String,Integer> recent){
  List<int[]> parts=new ArrayList<>();for(int d:limits.fractionDenominators())for(int n=1;n<d;n++)parts.add(new int[]{n,d});int wholes=skill.id.equals("fracMixedMul")?9:1,count=parts.size()*wholes*12*2;
  return IndexedQuestionSupply.choose(count,index->{boolean reversed=index%2==1;index/=2;int k=index%12+1;index/=12;int w=skill.id.equals("fracMixedMul")?index%9+1:0;int[] f=parts.get(index/wholes);return make(skill.id,w,f[0],f[1],k,reversed);},random,limits,recent);
 }
 static Checker.Result check(Question q,List<String> answers){
  var p=givens(q);if(p==null||answers==null||answers.size()!=1||answers.get(0)==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"답 입력 필요");String input=Expression.normalize(answers.get(0).trim());if(input.isEmpty()||input.length()>120)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"답 입력 필요");if("fraction".equals(q.answerFormat)&&!input.contains("/"))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"분수로 입력 필요");if("decimal".equals(q.answerFormat)&&(!input.contains(".")||input.contains("/")))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"소수로 입력 필요");if(!input.matches("[+-]?\\d+(?:\\.\\d+)?(?:/[+-]?\\d+)?"))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"마지막 답은 수로 입력");
  try{if(!Expression.number(input).equals(p.left.value().mul(p.right.value())))return new Checker.Result(Checker.Status.WRONG_ANSWER,0,"이 답 확인");if("reduced".equals(q.kind)){if(input.contains("."))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"분수로 입력 필요");if(input.contains("/")){String[] parts=input.split("/");if(!new BigInteger(parts[0]).gcd(new BigInteger(parts[1])).equals(BigInteger.ONE))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"약분 필요");}}return new Checker.Result(Checker.Status.CORRECT,-1,"계산 확인 완료");}catch(RuntimeException ex){return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"수 입력 확인 필요");}
 }
 public static int errorPart(Question q,String raw){var p=givens(q);if(p==null||raw==null||raw.length()>120||FractionInput.invalidPart(raw)!=0)return 0;String[] pair=FractionInput.parts(raw);BigInteger n=new BigInteger(pair[0]),d=new BigInteger(pair[1]);Rational expected=p.left.value().mul(p.right.value());if(n.multiply(expected.d).equals(expected.n.multiply(d)))return 0;long numerator=p.left.improperNumerator()*p.right.improperNumerator(),denominator=(long)p.left.denominator*p.right.denominator;if(d.equals(expected.d)||d.equals(BigInteger.valueOf(denominator)))return 1;if(n.equals(expected.n)||n.equals(BigInteger.valueOf(numerator)))return 2;return 0;}
}
